// Parse and validate input parameters with security checks
const input = $input.item.json.body || $input.item.json;

// Validation functions to prevent shell injection
function validateNodeName(nodeName) {
  if (!nodeName) {
    throw new Error('node_name is required');
  }

  const str = String(nodeName).trim();

  // Node names should be alphanumeric with hyphens only
  const nodeNamePattern = /^[a-zA-Z0-9-]+$/;
  if (!nodeNamePattern.test(str) || str.length > 63) {
    throw new Error('node_name contains invalid characters or is too long');
  }

  // Reject names that could be command injection attempts
  if (str.startsWith('-') || str.endsWith('-')) {
    throw new Error('node_name format is invalid');
  }

  return str;
}

function validateRequestId(requestId) {
  if (!requestId) {
    return `storage-${Date.now()}`;
  }

  const str = String(requestId).trim();

  // Allow only alphanumeric, hyphens, and underscores
  const requestIdPattern = /^[a-zA-Z0-9_-]+$/;
  if (!requestIdPattern.test(str) || str.length > 100) {
    throw new Error('request_id contains invalid characters or is too long');
  }

  return str;
}

function validateStorageClass(storageClass) {
  if (!storageClass) return 'local-path';

  const str = String(storageClass).trim();

  // Storage class names should be alphanumeric with hyphens
  const storageClassPattern = /^[a-z0-9-]+$/;
  if (!storageClassPattern.test(str) || str.length > 63) {
    throw new Error('storage_class contains invalid characters or is too long');
  }

  return str;
}

function validateProxmoxNode(proxmoxNode) {
  if (!proxmoxNode) return 'pve01';

  const str = String(proxmoxNode).trim();

  // Proxmox node names should be alphanumeric with hyphens
  const nodePattern = /^[a-zA-Z0-9-]+$/;
  if (!nodePattern.test(str) || str.length > 63) {
    throw new Error('proxmox_node contains invalid characters or is too long');
  }

  return str;
}

function validateRequestedBy(requestedBy) {
  if (!requestedBy) return 'cortex-autonomous';

  const str = String(requestedBy).trim();

  // Allow alphanumeric, hyphens, underscores, and @ for email
  const requestedByPattern = /^[a-zA-Z0-9._@-]+$/;
  if (!requestedByPattern.test(str) || str.length > 100) {
    throw new Error('requested_by contains invalid characters or is too long');
  }

  return str;
}

function validateNotifyChannel(channel) {
  if (!channel) return 'cortex-infra';

  const str = String(channel).trim();

  // Slack channel names: alphanumeric, hyphens, underscores
  const channelPattern = /^[a-z0-9_-]+$/;
  if (!channelPattern.test(str) || str.length > 80) {
    throw new Error('notify_channel contains invalid characters or is too long');
  }

  return str;
}

try {
  const params = {
    node_name: validateNodeName(input.node_name),
    size_gb: parseInt(input.size_gb) || 50,
    storage_class: validateStorageClass(input.storage_class),
    dry_run: input.dry_run === true || input.dry_run === 'true',
    notify_channel: validateNotifyChannel(input.notify_channel),
    request_id: validateRequestId(input.request_id),
    requested_by: validateRequestedBy(input.requested_by),
    proxmox_node: validateProxmoxNode(input.proxmox_node),
    vm_id: parseInt(input.vm_id)
  };

  // Additional validation
  const errors = [];
  if (params.size_gb < 1 || params.size_gb > 1000) {
    errors.push('size_gb must be between 1 and 1000');
  }
  if (!params.vm_id || isNaN(params.vm_id)) {
    errors.push('vm_id is required and must be a valid integer');
  }

  if (errors.length > 0) {
    return [{
      json: {
        valid: false,
        errors: errors,
        params: params
      }
    }];
  }

  return [{
    json: {
      valid: true,
      params: params,
      timestamp: new Date().toISOString()
    }
  }];
} catch (error) {
  return [{
    json: {
      valid: false,
      errors: [`Input validation failed: ${error.message}`],
      params: {}
    }
  }];
}

// Check current disk usage and determine expansion needs
const params = $input.first().json.params;
const vmStatus = $input.last().json.data;

const currentDiskSize = vmStatus?.maxdisk || 0;
const currentDiskUsed = vmStatus?.disk || 0;
const usagePercent = currentDiskSize > 0 ? (currentDiskUsed / currentDiskSize) * 100 : 0;

return [{
  json: {
    params: params,
    vm_status: {
      name: vmStatus?.name,
      status: vmStatus?.status,
      current_disk_gb: Math.round(currentDiskSize / 1073741824),
      used_disk_gb: Math.round(currentDiskUsed / 1073741824),
      usage_percent: Math.round(usagePercent)
    },
    expansion: {
      new_size_gb: params.size_gb,
      disk_to_expand: 'scsi0',
      needs_expansion: true
    }
  }
}];

// Parse verification output and prepare result
const params = $('Analyze Storage').item.json.params;
const vmStatus = $('Analyze Storage').item.json.vm_status;
const verifyOutput = $input.item.json.stdout || '';

// Parse df output: Filesystem Size Used Avail Use% Mounted
const parts = verifyOutput.trim().split(/\s+/);
const newSize = parts[1] || 'unknown';
const newUsed = parts[2] || 'unknown';
const newAvail = parts[3] || 'unknown';
const newUsePercent = parts[4] || 'unknown';

return [{
  json: {
    success: true,
    action: 'storage_expansion',
    request_id: params.request_id,
    node: params.node_name,
    before: {
      size_gb: vmStatus.current_disk_gb,
      used_gb: vmStatus.used_disk_gb,
      usage_percent: vmStatus.usage_percent
    },
    after: {
      size: newSize,
      used: newUsed,
      available: newAvail,
      usage_percent: newUsePercent
    },
    expansion_gb: params.size_gb,
    timestamp: new Date().toISOString(),
    requested_by: params.requested_by
  }
}];

// Prepare dry-run result without executing
const data = $input.item.json;

return [{
  json: {
    success: true,
    dry_run: true,
    action: 'storage_expansion',
    request_id: data.params.request_id,
    node: data.params.node_name,
    would_execute: [
      `Proxmox: Expand ${data.expansion.disk_to_expand} by ${data.expansion.new_size_gb}GB`,
      `SSH: growpart /dev/sda 3`,
      `SSH: resize2fs /dev/sda3`
    ],
    current_status: data.vm_status,
    timestamp: new Date().toISOString()
  }
}];
